import{_ as e,o as t,c as r,a6 as o}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"設計パターンの索引","description":"","frontmatter":{"title":"設計パターンの索引","study":{"source":"設計の手帖","kind":"索引","status":"既存原稿","summary":"分類: 振る舞い 方法を差し替える 使う場面: 送料や割引方式が増える Strategy・State・Command 分類: 振る舞い 状態と遷移を明示する 使う場面: 状態ごとの条件分岐が増える"}},"headers":[],"relativePath":"design/pattern-index.md","filePath":"design/pattern-index.md"}'),p={name:"design/pattern-index.md"};function d(n,a,i,h,s,l){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="設計パターンの索引" tabindex="-1">設計パターンの索引 <a class="header-anchor" href="#設計パターンの索引" aria-label="Permalink to &quot;設計パターンの索引&quot;">​</a></h1><h2 id="strategy" tabindex="-1">Strategy <a class="header-anchor" href="#strategy" aria-label="Permalink to &quot;Strategy&quot;">​</a></h2><p>分類: 振る舞い</p><p>方法を差し替える</p><p>使う場面: 送料や割引方式が増える</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><p>分類: 振る舞い</p><p>状態と遷移を明示する</p><p>使う場面: 状態ごとの条件分岐が増える</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="command" tabindex="-1">Command <a class="header-anchor" href="#command" aria-label="Permalink to &quot;Command&quot;">​</a></h2><p>分類: 振る舞い</p><p>操作を一つの単位にする</p><p>使う場面: 履歴・キュー・Undo を扱う</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="observer" tabindex="-1">Observer <a class="header-anchor" href="#observer" aria-label="Permalink to &quot;Observer&quot;">​</a></h2><p>分類: 振る舞い</p><p>変化を購読者へ知らせる</p><p>使う場面: 一つの変化を複数箇所が使う</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="template-method" tabindex="-1">Template Method <a class="header-anchor" href="#template-method" aria-label="Permalink to &quot;Template Method&quot;">​</a></h2><p>分類: 振る舞い</p><p>共通の流れを固定する</p><p>使う場面: 手順の一部だけ派生で変える</p><p><a href="/study/design/notebook/behavior.html">Strategy・State・Command</a></p><h2 id="mediator" tabindex="-1">Mediator <a class="header-anchor" href="#mediator" aria-label="Permalink to &quot;Mediator&quot;">​</a></h2><p>分類: 振る舞い</p><p>調整の窓口を作る</p><p>使う場面: 部品同士の相互依存が増える</p><p><a href="/study/design/notebook/events.html">Observer とイベント設計</a></p><h2 id="factory-factory-method" tabindex="-1">Factory / Factory Method <a class="header-anchor" href="#factory-factory-method" aria-label="Permalink to &quot;Factory / Factory Method&quot;">​</a></h2><p>分類: 生成</p><p>作る手順や判断を集める</p><p>使う場面: 生成時の実装選択が散らばる</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="abstract-factory" tabindex="-1">Abstract Factory <a class="header-anchor" href="#abstract-factory" aria-label="Permalink to &quot;Abstract Factory&quot;">​</a></h2><p>分類: 生成</p><p>関連する製品を一式作る</p><p>使う場面: UI 部品の組を交換したい</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="builder" tabindex="-1">Builder <a class="header-anchor" href="#builder" aria-label="Permalink to &quot;Builder&quot;">​</a></h2><p>分類: 生成</p><p>段階的に組み立てる</p><p>使う場面: 任意項目や組み立て手順が多い</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="singleton" tabindex="-1">Singleton <a class="header-anchor" href="#singleton" aria-label="Permalink to &quot;Singleton&quot;">​</a></h2><p>分類: 生成</p><p>一つの実体とアクセス点</p><p>使う場面: 一つ必要か、共有が必要かを検討</p><p><a href="/study/design/notebook/creation.html">Factory・Builder・Singleton</a></p><h2 id="adapter" tabindex="-1">Adapter <a class="header-anchor" href="#adapter" aria-label="Permalink to &quot;Adapter&quot;">​</a></h2><p>分類: 構造</p><p>異なる契約をつなぐ</p><p>使う場面: 外部 API を自分の契約に合わせる</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="decorator" tabindex="-1">Decorator <a class="header-anchor" href="#decorator" aria-label="Permalink to &quot;Decorator&quot;">​</a></h2><p>分類: 構造</p><p>同じ契約のまま機能を重ねる</p><p>使う場面: ログやキャッシュを付け外す</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="facade" tabindex="-1">Facade <a class="header-anchor" href="#facade" aria-label="Permalink to &quot;Facade&quot;">​</a></h2><p>分類: 構造</p><p>使いやすい入口を作る</p><p>使う場面: 複数の低水準操作をまとめる</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="proxy" tabindex="-1">Proxy <a class="header-anchor" href="#proxy" aria-label="Permalink to &quot;Proxy&quot;">​</a></h2><p>分類: 構造</p><p>アクセスを代理する</p><p>使う場面: 遅延生成やリモート呼び出し</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="composite" tabindex="-1">Composite <a class="header-anchor" href="#composite" aria-label="Permalink to &quot;Composite&quot;">​</a></h2><p>分類: 構造</p><p>単体と集合を同じように扱う</p><p>使う場面: ツリー構造を同じ操作で処理</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p><h2 id="bridge" tabindex="-1">Bridge <a class="header-anchor" href="#bridge" aria-label="Permalink to &quot;Bridge&quot;">​</a></h2><p>分類: 構造</p><p>抽象と実装を別々に拡張する</p><p>使う場面: 二つの軸の組み合わせが増える</p><p><a href="/study/design/notebook/structure.html">Adapter・Decorator・Facade</a></p>',81)])])}const m=e(p,[["render",d]]);export{u as __pageData,m as default};
